"""A very small evaluator for a subset of Forth.

Supported words:
  +, -, *, /        integer arithmetic
  dup, drop, swap, over   stack manipulation
  : name ... ;      user-defined words

Words are case-insensitive. A number is a sequence of digits, optionally
preceded by a single minus sign.
"""

import re

_NUMBER_RE = re.compile(r"^-?\d+$")


class StackUnderflowError(Exception):
    """Raised when a word needs more values than are on the stack."""


class _Number:
    """A literal number to be pushed onto the stack."""

    def __init__(self, value):
        self.value = value

    def execute(self, stack, words):
        stack.append(self.value)


class _UserWord:
    """A user-defined word, stored as a compiled list of operations."""

    def __init__(self, body):
        self.body = body

    def execute(self, stack, words):
        for op in self.body:
            op.execute(stack, words)


class _Reference:
    """A word name that was not defined when a word was compiled.

    It is resolved against the current word table at execution time, so a
    definition keeps referring to the word as it was at compile time while
    still tolerating words that only exist later.
    """

    def __init__(self, name):
        self.name = name

    def execute(self, stack, words):
        if self.name not in words:
            raise ValueError("undefined operation")
        words[self.name].execute(stack, words)


class _Builtin:
    """A built-in word implemented as a function on the stack."""

    def __init__(self, fn):
        self.fn = fn

    def execute(self, stack, words):
        self.fn(stack)


def _check(stack, count):
    if len(stack) < count:
        raise StackUnderflowError("Insufficient number of items in stack")


def _add(stack):
    _check(stack, 2)
    b = stack.pop()
    a = stack.pop()
    stack.append(a + b)


def _sub(stack):
    _check(stack, 2)
    b = stack.pop()
    a = stack.pop()
    stack.append(a - b)


def _mul(stack):
    _check(stack, 2)
    b = stack.pop()
    a = stack.pop()
    stack.append(a * b)


def _div(stack):
    _check(stack, 2)
    b = stack.pop()
    a = stack.pop()
    if b == 0:
        raise ZeroDivisionError("divide by zero")
    quotient = abs(a) // abs(b)
    if (a < 0) != (b < 0):
        quotient = -quotient
    stack.append(quotient)


def _dup(stack):
    _check(stack, 1)
    stack.append(stack[-1])


def _drop(stack):
    _check(stack, 1)
    stack.pop()


def _swap(stack):
    _check(stack, 2)
    stack[-1], stack[-2] = stack[-2], stack[-1]


def _over(stack):
    _check(stack, 2)
    stack.append(stack[-2])


_BUILTINS = {
    "+": _Builtin(_add),
    "-": _Builtin(_sub),
    "*": _Builtin(_mul),
    "/": _Builtin(_div),
    "dup": _Builtin(_dup),
    "drop": _Builtin(_drop),
    "swap": _Builtin(_swap),
    "over": _Builtin(_over),
}


def _compile(tokens, words):
    """Compile the tokens of a word definition into a list of operations.

    Names that are already defined are bound to their current definition so
    that redefining a word later does not change what older definitions do.
    """
    body = []
    for token in tokens:
        if _NUMBER_RE.match(token):
            body.append(_Number(int(token)))
        else:
            name = token.lower()
            body.append(words.get(name, _Reference(name)))
    return body


def _define(tokens, words):
    if len(tokens) < 2:
        raise ValueError("illegal operation")
    name = tokens[1]
    if _NUMBER_RE.match(name):
        raise ValueError("illegal operation")
    body_tokens = []
    for token in tokens[2:]:
        if token.lower() == ";":
            break
        body_tokens.append(token)
    words[name.lower()] = _UserWord(_compile(body_tokens, words))


def _execute(tokens, stack, words):
    for token in tokens:
        if _NUMBER_RE.match(token):
            stack.append(int(token))
        else:
            name = token.lower()
            if name not in words:
                raise ValueError("undefined operation")
            words[name].execute(stack, words)


def evaluate(input_data):
    """Evaluate a list of Forth lines and return the resulting stack."""
    stack = []
    words = dict(_BUILTINS)
    for line in input_data:
        tokens = line.split()
        if not tokens:
            continue
        if tokens[0].lower() == ":":
            _define(tokens, words)
        else:
            _execute(tokens, stack, words)
    return stack
